#include<bits/stdc++.h>
using namespace std;

static constexpr size_t maxN=2000;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n,m;cin>>n>>m;
    vector<vector<int>>a(n,vector<int>(m));
    for(int i=0;i<n;++i){
        for(int j=0;j<m;++j){
            cin>>a[i][j];
        }
    }

    vector<bitset<maxN>>bt(n);
    vector<bitset<maxN>>bs(1000);
    for(int i=0;i<m;++i){
        for(int j=0;j<n;++j){
            bs[a[j][i]].set(j);
        }
        for(int j=0;j<n;++j){
            bt[j]^=bs[a[j][i]];
        }
        for(int j=0;j<n;++j){
            bs[a[j][i]].reset(j);
        }
    }

    int ans=0;
    for(int i=0;i<n;++i)ans+=bt[i].count();
    if(m&1)ans-=n;
    cout<<ans/2<<endl;
}

#include<bits/stdc++.h>
using namespace std;
#define rep(i,n) for(int (i)=0;(i)<(n);(i)++)

int main(void){
    cin.tie(0);ios::sync_with_stdio(false);
    int N,M;
    cin >> N >> M;
    short A[M][N];
    rep(i,N) rep(j,M) cin >> A[j][i];
    bool cnt[N][N];
    rep(i,N) rep(j,N) cnt[i][j]=false;
    rep(i,M){
        rep(j,N) for(int k=j+1;k<N;k++) cnt[j][k]^=(A[i][j]==A[i][k]);
    }
    int ans=0;
    rep(i,N) for(int j=i+1;j<N;j++) ans+=cnt[i][j];
    cout << ans << endl;
}
